// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type RateLimiter = { limit(options: { key: string }): Promise<{ success: boolean }> };
type Env = { SUBMIT_RATE_LIMIT: RateLimiter };

// Same rule as the Vercel Firewall's "Rate-limit form submissions": 5 POSTs to /api/submit per IP per 60 s.
// A zone rate-limit rule on the free plan only allows a 10 s window, so it lives here.
const worker = {
  async fetch(request: Request, env: Env, ctx: unknown) {
    if (request.method === "POST" && new URL(request.url).pathname === "/api/submit") {
      const { success } = await env.SUBMIT_RATE_LIMIT.limit({ key: request.headers.get("cf-connecting-ip") ?? "unknown" });
      if (!success) return new Response("Too Many Requests", { status: 429 });
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;
